import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
import {createCharacter} from '@nautilus-engine/map-core/rules';
import {createMeleeState,equipmentLoadout,stageMeleeCommand,stageMeleeTick,readMeleePresentation,openMeleeState,meleeEquipment,listMeleeEquipment} from '@nautilus-engine/map-core/melee';
import {listFantasyEquipmentArt} from '@nautilus-engine/map-core/fantasy-equipment-art';
import {prepareNativeMeleeActor} from '@nautilus-engine/map-core/native-actors/melee/three';
let state=createMeleeState({id:'installed-duel',seed:123,content:{id:'installed-fixture',version:1,sourcePin:'796c1e73644a30a3061d2f38b3bcccab49519453'},actors:[{id:'player',equipment:equipmentLoadout('sword')},{id:'target',equipment:equipmentLoadout('mace','round-wood-shield')}]}),characters=[createCharacter({id:'player',stats:{strength:50,dexterity:90,agility:80},resources:{hp:83}}),createCharacter({id:'target',stats:{strength:50},resources:{hp:91}})];
const bodies=[{actorId:'player',revision:0,position:{x:0,y:0,h:0},headingDeg:0,radiusM:.28,heightM:1.8,floorId:'ground'},{actorId:'target',revision:0,position:{x:1.4,y:0,h:0},headingDeg:180,radiusM:.28,heightM:1.8,floorId:'ground'}],context=()=>({revision:0,characters,bodies,world:{id:'installed-yard',revision:0},owns:()=>true,permitted:()=>({ok:true,reason:''}),traceContact:q=>({clear:true,world:q.world,sourceRevision:q.sourceBody.revision,targetRevision:q.targetBody.revision,blockerId:null})});
const accepted=stageMeleeCommand(state,{type:'attack',commandId:'installed-strike',expectedRevision:0,actorId:'player',targetId:'target',modeId:'slash'},context());assert(accepted.ok&&!accepted.repeated);state=accepted.next;assert.equal(characters[0].resources.ap,15);for(let tick=1;tick<=6;tick++){const result=stageMeleeTick(state,{tick,stepId:state.id+'/step/'+tick},context());assert(result.ok&&!result.repeated);state=result.next;characters=result.characters;}
assert.equal(state.events.filter(e=>e.type==='melee-impact').length,1);assert.equal(state.actors[0].action.outcome.damageType,'slash');assert.equal(characters[1].resources.hp,71);assert.equal(characters[0].resources.hp,83);assert.deepEqual(openMeleeState(JSON.stringify(state)),state);assert.equal(readMeleePresentation(state,'player',0).phase,'impact');assert.equal(listFantasyEquipmentArt().length,15);assert.equal(typeof prepareNativeMeleeActor,'function');assert.equal(typeof globalThis.document,'undefined');
const twoHands=['blacksmith-hammer','pick','spear','halberd','bow','crossbow'];assert.deepEqual(listMeleeEquipment().filter(r=>r.hands===2).map(r=>r.id).sort(),[...twoHands].sort());
for(const art of listFantasyEquipmentArt()){const r=meleeEquipment(art.id);if(twoHands.includes(art.id)){assert.equal(r.hands,2);assert(art.grip.off);assert.notDeepEqual(art.grip.off.position,art.grip.main.position);}else if(r.slot==='off'){assert.equal(r.hands,1);assert.deepEqual(art.grip.off.position,art.grip.main.position);}else assert.equal(art.grip.off,null);}
assert.throws(()=>equipmentLoadout('pick','round-wood-shield'),{code:'MELEE_TWO_HANDS'});
let pickState=createMeleeState({id:'installed-pick',seed:123,content:state.content,actors:[{id:'player',equipment:equipmentLoadout('pick')},{id:'target',equipment:equipmentLoadout('mace')}]});
bodies[0].position.x=.12;bodies[0].revision++;const beforePick={state:structuredClone(pickState),characters:structuredClone(characters)};
const rejectedPick=stageMeleeCommand(pickState,{type:'equip',commandId:'bad-pick-shield',expectedRevision:0,actorId:'player',equipment:{main:{id:'pick',version:1},off:{id:'round-wood-shield',version:1}}},context());assert.equal(rejectedPick.code,'MELEE_TWO_HANDS');assert.deepEqual({state:pickState,characters},beforePick);
const acceptedPick=stageMeleeCommand(pickState,{type:'attack',commandId:'pick-strike',expectedRevision:0,actorId:'player',targetId:'target',modeId:'pick'},context());assert(acceptedPick.ok&&!acceptedPick.repeated);pickState=acceptedPick.next;
for(let tick=1;tick<=9;tick++){const result=stageMeleeTick(pickState,{tick,stepId:pickState.id+'/step/'+tick},context());assert(result.ok&&!result.repeated);pickState=result.next;characters=result.characters;}
assert.equal(pickState.actors[0].action.outcome.damageType,'piercing');assert(pickState.actors[0].action.outcome.contact);assert.equal(characters[0].resources.ap,beforePick.characters[0].resources.ap-2);assert.equal(characters[0].resources.stamina,beforePick.characters[0].resources.stamina-7);assert.equal(pickState.actors[0].equipment.off,null);
const entries=['melee','melee/equipment','fantasy-equipment-art','fantasy-equipment-art/three','native-actors/melee/three'],resolved=entries.map(entry=>fileURLToPath(import.meta.resolve('@nautilus-engine/map-core/'+entry)));assert(resolved.every(p=>p.includes('node_modules')));console.log(JSON.stringify({status:'passed',resolved,impact:state.actors[0].action.outcome,pickImpact:pickState.actors[0].action.outcome,pickShieldRefusal:rejectedPick.code,twoHandedRoster:twoHands,characters:characters.map(c=>({id:c.id,resources:c.resources}))}));
